CREATE OR REPLACE VIEW library_likutey_halajot_investigative_audit_v1 AS
WITH events AS (
 SELECT jsonb_build_object('search_record_type','page_literal','document_id',s.document_id,'document_code',s.document_code,'pdf_page',s.pdf_page,'printed_page',s.printed_page,'page_text',s.page_text,'page_literal_hash',s.page_literal_hash,'page_first_source_run_id',s.source_run_id,'has_text',true,'is_blank',false,'document_part',s.document_part,'structural_status',s.structural_status,'final_page_status',s.final_ingestion_decision,'unit_type',s.unit_type,'unit_label',s.unit_label,'unit_number',s.unit_number,'evidence_level','literal_page','is_authoritative_relation',false,'is_searchable',true,'warnings','[]'::jsonb) data FROM library_likutey_halajot_search_ready_v2 s
 UNION ALL SELECT jsonb_build_object('search_record_type','structural_page','document_id',p.document_id,'document_code',p.document_code,'pdf_page',p.pdf_page,'printed_page',p.printed_page,'page_first_source_run_id','likutey_halajot_page_first_v1','has_text',p.has_text,'is_blank',p.is_blank,'document_part',p.document_part,'structural_status',p.structural_status,'final_page_status',p.final_page_status,'unit_type',p.unit_type,'unit_label',p.unit_label,'unit_number',p.unit_number,'evidence_level',CASE WHEN p.has_text THEN 'contextual_hint' ELSE 'audit_only' END,'is_authoritative_relation',false,'is_searchable',p.has_text,'warnings',p.warnings) FROM library_likutey_halajot_page_final_status_v2 p
 UNION ALL SELECT jsonb_build_object('search_record_type','fine_zone','document_id',z.document_id,'document_code',d.document_code,'pdf_page',z.pdf_page,'printed_page',a.printed_page_number,'page_first_source_run_id',z.source_run_id,'has_text',true,'is_blank',false,'document_part',d.document_part,'structural_status',d.structural_status,'unit_type',d.unit_type,'unit_label',d.unit_label,'unit_number',d.unit_number,'structural_detector_run_id',z.structural_detector_run_id,'fine_zone_id',z.id,'fine_zone_type',z.zone_type,'fine_zone_quote',z.text_quote,'fine_zone_confidence',z.confidence,'fine_zone_validation_status',z.validation_status,'marker_kind',z.marker_kind,'marker_value',z.marker_value,'source_or_commentator',z.source_or_commentator,'visible_note_number_from_zone',z.visible_note_number,'evidence_level',CASE WHEN z.validation_status='validated' THEN 'validated_zone' ELSE 'contextual_hint' END,'is_authoritative_relation',false,'is_searchable',true,'warnings',z.warnings) FROM library_likutey_halajot_fine_zones_v1 z JOIN library_page_anchors_v2 a ON a.page_anchor_id=z.page_anchor_id LEFT JOIN library_likutey_halajot_structural_v2 d ON d.page_anchor_id=z.page_anchor_id
 UNION ALL SELECT jsonb_build_object('search_record_type','note_source_unit','document_id',n.document_id,'document_code',d.document_code,'pdf_page',n.pdf_page,'printed_page',a.printed_page_number,'page_first_source_run_id','likutey_halajot_page_first_v1','has_text',true,'is_blank',false,'document_part',d.document_part,'structural_status',d.structural_status,'unit_type',d.unit_type,'unit_label',d.unit_label,'unit_number',d.unit_number,'fine_zone_id',n.parent_fine_zone_id,'marker_value',n.marker_value,'source_or_commentator',n.source_or_commentator,'note_source_unit_id',n.id,'note_source_unit_type',n.unit_type,'note_source_unit_role',n.unit_role,'visible_note_number',n.visible_note_number,'note_source_quote',n.text_quote,'note_source_validation_status',n.validation_status,'halakhah_header_hint',n.halakhah_header_hint,'evidence_level',CASE WHEN n.validation_status='validated' AND n.unit_type='numbered_note' THEN 'validated_note' ELSE 'contextual_hint' END,'is_authoritative_relation',false,'is_searchable',true,'warnings',n.warnings) FROM library_likutey_halajot_note_source_units_v1 n JOIN library_page_anchors_v2 a ON a.page_anchor_id=n.page_anchor_id LEFT JOIN library_likutey_halajot_structural_v2 d ON d.page_anchor_id=n.page_anchor_id
 UNION ALL SELECT jsonb_build_object('search_record_type','nominal_reference','document_id',r.document_id,'document_code',r.document_code,'pdf_page',r.pdf_page,'printed_page',r.printed_page,'page_first_source_run_id',r.source_run_id,'has_text',true,'is_blank',false,'document_part',d.document_part,'structural_status',d.structural_status,'unit_type',d.unit_type,'unit_label',d.unit_label,'unit_number',d.unit_number,'structural_detector_run_id',r.structural_detector_run_id,'fine_zone_id',r.parent_fine_zone_id,'marker_kind',r.marker_kind,'marker_value',r.marker_value,'note_source_unit_id',r.parent_note_source_unit_id,'visible_note_number',r.visible_note_number,'halakhah_header_hint',r.halakhah_header_hint,'nominal_reference_id',r.id,'surface_form',r.surface_form,'normalized_reference_name',r.normalized_reference_name,'reference_kind',r.reference_kind,'nominal_reference_quote',r.text_quote,'nominal_validation_status',r.validation_status,'evidence_level','validated_nominal_reference','is_authoritative_relation',false,'is_searchable',true,'warnings',r.warnings) FROM library_likutey_halajot_nominal_references_v1 r LEFT JOIN library_likutey_halajot_structural_v2 d ON d.page_anchor_id=r.page_anchor_id
 UNION ALL SELECT jsonb_build_object('search_record_type','resolved_reference','document_id',r.document_id,'document_code',r.document_code,'pdf_page',r.pdf_page,'printed_page',r.printed_page,'page_first_source_run_id',r.source_run_id,'has_text',true,'is_blank',false,'document_part',d.document_part,'structural_status',d.structural_status,'unit_type',d.unit_type,'unit_label',d.unit_label,'unit_number',d.unit_number,'structural_detector_run_id',r.structural_detector_run_id,'fine_zone_id',r.parent_fine_zone_id,'marker_kind',r.marker_kind,'marker_value',r.marker_value,'note_source_unit_id',r.parent_note_source_unit_id,'visible_note_number',r.visible_note_number,'halakhah_header_hint',r.halakhah_header_hint,'nominal_reference_id',r.id,'surface_form',r.surface_form,'normalized_reference_name',r.normalized_reference_name,'reference_kind',r.reference_kind,'nominal_reference_quote',r.text_quote,'nominal_validation_status',r.validation_status,'reference_resolution_id',x.id,'resolution_decision',x.resolution_decision,'resolved_reference_kind',x.resolved_reference_kind,'resolved_normalized_reference_name',x.resolved_normalized_reference_name,'resolution_method',x.resolution_method,'resolution_confidence',x.confidence,'resolution_quote',x.evidence_quote,'resolution_warnings',x.warnings,'evidence_level',CASE WHEN x.resolution_decision='resolved_canonical_reference' THEN 'resolved_investigative_reference' ELSE 'contextual_hint' END,'is_authoritative_relation',false,'is_searchable',x.resolution_decision<>'rejected_false_positive','warnings',x.warnings) FROM library_likutey_halajot_nominal_reference_resolution_v1 x JOIN library_likutey_halajot_nominal_references_v1 r ON r.id=x.nominal_reference_id LEFT JOIN library_likutey_halajot_structural_v2 d ON d.page_anchor_id=r.page_anchor_id
)
SELECT x.* FROM events CROSS JOIN LATERAL jsonb_to_record(events.data) AS x(search_record_type text,document_id uuid,document_code text,pdf_page integer,printed_page integer,page_text text,page_literal_hash text,page_first_source_run_id text,has_text boolean,is_blank boolean,document_part text,structural_status text,final_page_status text,unit_type text,unit_label text,unit_number text,structural_detector_run_id text,fine_zone_id uuid,fine_zone_type text,fine_zone_quote text,fine_zone_confidence numeric,fine_zone_validation_status text,marker_kind text,marker_value text,source_or_commentator text,visible_note_number_from_zone text,note_source_unit_id uuid,note_source_unit_type text,note_source_unit_role text,visible_note_number text,note_source_quote text,note_source_validation_status text,halakhah_header_hint text,nominal_reference_id uuid,surface_form text,normalized_reference_name text,reference_kind text,nominal_reference_quote text,nominal_validation_status text,reference_resolution_id uuid,resolution_decision text,resolved_reference_kind text,resolved_normalized_reference_name text,resolution_method text,resolution_confidence numeric,resolution_quote text,resolution_warnings jsonb,evidence_level text,is_authoritative_relation boolean,is_searchable boolean,warnings jsonb);
CREATE OR REPLACE VIEW library_likutey_halajot_investigative_search_v1 AS SELECT * FROM library_likutey_halajot_investigative_audit_v1 WHERE is_searchable AND (resolution_decision IS NULL OR resolution_decision<>'rejected_false_positive');
